async function t(r,e={},o){return window.__TAURI_INTERNALS__.invoke(r,e,o)}const n={getProviders(){return t("get_providers")},search(r,e=0,o=20){return t("search",{keyword:r,skip:e,take:o})},getEntity(r){return t("get_entity",{url:r})},getChapter(r,e){return t("get_chapter",{entityUrl:r,chapterUrl:e})},getImage(r,e){return t("get_image",{entityUrl:r,url:e})},getProposal(r,e=20){return t("get_proposal",{engineName:r,take:e})},getBookshelf(){return t("get_bookshelf")},addToBookshelf(r){return t("add_to_bookshelf",{url:r.url,name:r.name,imageUrl:r.image_url,descript:r.descript,chaptersCount:r.chapters_count})},removeFromBookshelf(r){return t("remove_from_bookshelf",{url:r})},updateReadingProgress(r,e,o){return t("update_reading_progress",{url:r,chapter:e,page:o})}};export{n as tauriAdapter};
